const clone=x=>JSON.parse(JSON.stringify(x)), $=s=>document.querySelector(s), money=x=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP'}).format(Number(x)||0), round=x=>Math.round((Number(x)+Number.EPSILON)*100)/100, sum=a=>round(a.reduce((s,n)=>s+(Number(n)||0),0)), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), attr=esc, uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,8), today=()=>{let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}, dateFmt=s=>s?new Date(s+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short'}):'—', monthName=m=>new Date(m+'-01T12:00:00').toLocaleDateString('en-GB',{month:'long',year:'numeric'}), number=v=>v===''?null:Number(v), isMonth=(d,m)=>String(d||'').slice(0,7)===m;
let state=null, month='', page='overview', shared=false, revision=0, queue=Promise.resolve(), dirty=false, conflict=false, status='Locked', timer, editVersion=0, pendingWrites=0, sessionGeneration=0, ownerId=null;
const planText=(key,fallback='')=>esc(state?.privatePlan?.[key]||fallback);
const tabs=[['overview','◉','Overview'],['budget','▤','Monthly budget'],['payday','⇄','Payday & Pots'],['debts','↘','Debt tracker'],['subscriptions','✓','Subscriptions'],['activity','+','Income & spending'],['review','◷','Sunday review'],['goals','◎','Recovery plan'],['settings','⚙','Data & settings']];
