function notify(msg){const el=$('#toast');el.textContent=msg;el.classList.remove('hidden');clearTimeout(timer);timer=setTimeout(()=>el.classList.add('hidden'),4000)}
function setStatus(msg){status=msg;$('#saveStatus').textContent=msg}
function save(){
 if(!shared||!state)return;
 dirty=true; const version=++editVersion, generation=sessionGeneration;
 if(conflict){setStatus('Conflict · export before reloading');return;}
 const payload=clone(state); pendingWrites++;setStatus('Saving…');
 queue=queue.then(async()=>{
  if(conflict||generation!==sessionGeneration)return;
  try{
   const next=await Cloud.write(revision,payload);
   if(generation!==sessionGeneration)return;
   if(next===null){conflict=true;setStatus('Conflict · export before reloading');notify('Another device saved first. Export your backup, then use Data & settings to reload the shared record.');return;}
   revision=next; if(version===editVersion){dirty=false;setStatus('Cloud · saved');}
  }catch(e){if(generation===sessionGeneration){dirty=true;setStatus('Not synced · retry or export');notify(e.message==='session'?'Session expired. Export a backup or sign in again using Data & settings.':'Changes not yet saved online. Retry or export a backup.');}}
 }).finally(()=>{if(generation===sessionGeneration)pendingWrites=Math.max(0,pendingWrites-1);});
}
function getMonth(m=month){if(!state.months[m]){const prev=Object.keys(state.months).filter(x=>x<m).sort().pop();const p=state.months[prev||Object.keys(state.months).sort()[0]];const dates=benefitDates(m);state.months[m]={amounts:clone(p.amounts),income:clone(p.income),saveTarget:p.saveTarget,pipDate:dates.pip[0]||'',cbDate:dates.cb[0]||'',moves:{},note:''};save()}return state.months[m]}
function benefitDates(m){const out={pip:[],cb:[]};for(const key of ['pip','cb']){const anchor=state.settings[key==='pip'?'pipAnchor':'cbAnchor']||Object.values(state.months).map(x=>x[key==='pip'?'pipDate':'cbDate']).find(Boolean);if(!anchor)continue;let d=new Date(anchor+'T12:00:00Z');if(!Number.isFinite(d.getTime()))continue;while(d.toISOString().slice(0,7)>m)d.setUTCDate(d.getUTCDate()-28);let stop=new Date(m+'-01T12:00:00Z');stop.setUTCMonth(stop.getUTCMonth()+1);let n=0;while(d<stop&&n++<200){let s=d.toISOString().slice(0,10);if(s.startsWith(m))out[key].push(s);d.setUTCDate(d.getUTCDate()+28)}}return out}
function amount(id,m=getMonth()){return Number(m.amounts[id]||0)}function inc(id,m=getMonth()){return Number(m.income[id]||0)}
function figures(){let m=getMonth(),income=sum(Object.values(m.income)),expenses=sum(Object.values(m.amounts)),wages=sum([inc('salary',m),inc('wife',m)]),bills=sum(state.items.filter(i=>i.account==='barclays').map(i=>amount(i.id,m))),personal=sum(state.items.filter(i=>i.account==='personal').map(i=>amount(i.id,m))),pots=sum(state.items.filter(i=>i.account==='pot').map(i=>amount(i.id,m))),weekly=sum(state.items.filter(i=>i.account==='weekly').map(i=>amount(i.id,m))),initialRaw=round(wages-bills-personal-pots),initial=Math.max(0,Math.min(weekly,initialRaw)),joint=round(initial+pots),gap=Math.max(0,-initialRaw),topup=round(Math.max(0,weekly-initial)),extra=sum(state.extra.filter(x=>isMonth(x.date,month)).map(x=>Math.max(0,x.amount-x.tax))),actualIncome=sum(state.receipts.filter(x=>(x.budgetMonth||x.date.slice(0,7))===month).map(x=>x.amount))+extra,actualSpend=sum(state.expenses.filter(x=>isMonth(x.date,month)).map(x=>x.amount)),debt=sum(state.debts.map(x=>x.balance)),start=sum(state.debts.map(x=>x.start));return {income,expenses,wages,bills,personal,pots,weekly,initial,joint,gap,topup,extra,actualIncome:round(actualIncome),actualSpend,debt,start,surplus:round(income-expenses),after:round(income-expenses-m.saveTarget)}}
function weeks(){let m=getMonth(),[y,mo]=month.split('-').map(Number),days=new Date(y,mo,0).getDate(),out=[],used={food:0,transport:0,fun:0};for(let d=1;d<=days;d+=7){let len=Math.min(7,days-d+1),o={date:`${month}-${String(d).padStart(2,'0')}`,end:d+len-1,days:len};for(let id of ['food','transport','fun']){o[id]=d+len-1===days?round(amount(id,m)-used[id]):round(amount(id,m)*len/days);used[id]=round(used[id]+o[id])}o.total=sum([o.food,o.transport,o.fun]);out.push(o)}return out}
function plannedMoves(){const f=figures(),m=getMonth(),w=weeks(),first=month+'-01',p=new Date(first+'T12:00:00');p.setDate(0);let pay=`${p.getFullYear()}-${String(p.getMonth()+1).padStart(2,'0')}-${String(p.getDate()).padStart(2,'0')}`;let arr=[{id:'joint',date:pay,from:'Barclays Joint',to:'Monzo Joint',amount:f.joint,note:'Fund only after both wages and current essential bills are covered.'},{id:'reserve',date:pay,from:'Monzo Joint main',to:'Weekly Spending Reserve',amount:f.initial,note:'Future weeks; not available to spend yet.'},...state.items.filter(x=>x.account==='pot').map(x=>({id:'pot-'+x.id,date:pay,from:'Monzo Joint main',to:x.name,amount:amount(x.id),note:'Roll unused money forward.'})),{id:'personal',date:pay,from:'Barclays Joint',to:'Personal Monzo',amount:f.personal,note:'Already included in the monthly budget.'}];let pip=Math.min(f.topup,Math.max(0,inc('pip')-(Number(state.settings.pipReserved)||0))),remain=round(f.topup-pip);if(pip>0)arr.push({id:'pip-top',date:m.pipDate||first,from:'Barclays → Monzo Joint',to:'Weekly Spending Reserve',amount:pip,note:'Only after PIP arrives and the claimant’s needs are fully funded.'});if(remain>0)arr.push({id:'reserve-gap',date:m.cbDate||first,from:'Available income (confirm)',to:'Weekly Spending Reserve',amount:remain,note:'Unfunded by wage/PIP plan; check affordability and timing.'});w.forEach((x,i)=>arr.push({id:'week-'+i,date:x.date,from:'Weekly Spending Reserve',to:'Monzo Joint main balance',amount:x.total,note:`${x.days} days · only release available cash.`}));if(m.saveTarget>0)arr.push({id:'save',date:m.cbDate||`${month}-28`,from:'Barclays → Monzo Joint',to:'Emergency Fund',amount:m.saveTarget,note:'Only if affordable after bills and essential costs.'});return arr.sort((a,b)=>a.date.localeCompare(b.date)||((a.id==='pip-top'||a.id==='reserve-gap')?-1:0))}
function metric(label,value,caption='',cls=''){return `<div class="card"><div class="label">${esc(label)}</div><div class="metric ${cls}">${esc(value)}</div><div class="mini">${esc(caption)}</div></div>`}
function note(s,warn=false){return `<div class="note ${warn?'warn':''}">${s}</div>`}
function field(label,html){return `<div class="field"><label>${esc(label)}</label>${html}</div>`}function valInput(v,action,attrs=''){return `<input ${attrs} value="${attr(v??'')}" data-edit="${attr(action)}">`}function num(v,action,attrs=''){return valInput(v,action,`type="number" step="0.01" min="0" ${attrs}`)}function opts(arr,selected){return arr.map(([v,t])=>`<option value="${attr(v)}" ${v===selected?'selected':''}>${esc(t)}</option>`).join('')}
function render(){let f=figures();$('#month').value=month;$('#title').textContent=tabs.find(t=>t[0]===page)[2];$('#nav').innerHTML=tabs.map(([id,ico,name])=>`<button class="${page===id?'active':''}" data-page="${id}"><span class="ico">${ico}</span>${name}</button>`).join('');$('#content').innerHTML=({overview,budget,payday,debts,subscriptions,activity,review,goals,settings})[page](f);}
function overview(f){const pct=Math.max(0,Math.min(100,state.settings.emergency/state.settings.target*100));const groups=[['Bills · Barclays',f.bills,'#536e82'],['Personal commitments',f.personal,'#9b8eb1'],['Joint Pots',f.pots,'#78a99d'],['Weekly spending',f.weekly,'#d1a05b'],['Savings target',getMonth().saveTarget,'#218067']];let moves=plannedMoves(),done=moves.filter(x=>getMonth().moves[x.id]?.done).length;let upcoming=moves.filter(x=>!getMonth().moves[x.id]?.done).slice(0,5);return `<div class="grid">${metric('Core income',money(f.income),'Excludes unconfirmed extras')}${metric('Planned expenditure',money(f.expenses),'Before emergency saving')}${metric('Projected surplus',money(f.surplus),'Before emergency saving',f.surplus>=0?'green':'red')}${metric('Identified debt',money(f.debt),'Unknown balances excluded')}</div><div class="section split"><div><div class="card"><div class="section-title"><h2>Monthly allocation</h2><button class="button" data-page="budget">Edit budget</button></div><div class="bigbar">${groups.map(([n,v,c])=>`<div title="${attr(n+' '+money(v))}" style="width:${Math.max(0,v/Math.max(f.income,f.expenses+getMonth().saveTarget,1)*100)}%;background:${c}"></div>`).join('')}</div><div class="legend">${groups.map(([n,v,c])=>`<div><span class="dot" style="background:${c}"></span>${esc(n)}<strong class="right">${money(v)}</strong></div>`).join('')}<div><span class="dot" style="background:#e8eff0"></span>Unallocated after saving<strong class="right ${f.after<0?'red':'green'}">${money(f.after)}</strong></div></div>${note('Illustrative term-time scenario: '+money(f.surplus+Number(state.settings.danceEstimate||0))+' surplus before saving with '+money(state.settings.danceEstimate)+' additional income. Actual extra receipts are tracked separately. Income must actually arrive; protect essentials and the claimant’s needs.')}</div><div class="card"><div class="section-title"><h2>Upcoming money movements</h2><button class="button" data-page="payday">Full schedule</button></div>${upcoming.length?upcoming.map(x=>`<div class="flow-step row between"><div><strong>${esc(x.to)}</strong><div class="mini">${dateFmt(x.date)} · from ${esc(x.from)}</div></div><strong>${money(x.amount)}</strong></div>`).join(''):'<div class="empty">All planned moves marked complete.</div>'}<div class="bar"><div style="width:${moves.length?done/moves.length*100:0}%"></div></div><div class="small muted">${done} of ${moves.length} transfers marked complete</div></div></div><div><div class="card"><h2>Emergency fund</h2><div class="metric green">${money(state.settings.emergency)}</div><div class="muted small">Target ${money(state.settings.target)}</div><div class="bar"><div style="width:${pct}%"></div></div><div class="row between small"><span>${Math.round(pct)}% funded</span><span>${money(Math.max(0,state.settings.target-state.settings.emergency))} to go</span></div><div class="row" style="margin-top:15px"><button class="button" data-page="activity">Record savings</button><button class="button" data-page="review">Update balance</button></div></div><div class="card"><h2>Debt progress</h2><div class="metric">${money(f.start-f.debt)}</div><div class="small muted">Net change from identified starting balances; negative means debt grew. New unknown balances affect comparability.</div><div class="bar"><div style="width:${Math.max(0,Math.min(100,(f.start-f.debt)/Math.max(1,f.start)*100))}%"></div></div><button class="button" data-page="debts">Update debt balances</button></div><div class="card"><h2>Recorded cash flow</h2><div class="row between"><span>Receipts</span><strong>${money(f.actualIncome)}</strong></div><div class="row between"><span>Expenses</span><strong>${money(f.actualSpend)}</strong></div><div class="row between"><span>Net recorded</span><strong>${money(f.actualIncome-f.actualSpend)}</strong></div><p class="small muted">Only logged entries; not your bank balance. Internal transfers are not expenses.</p><button class="button" data-page="activity">Log an entry</button></div></div></div><div class="card"><h2>Start here</h2><div class="grid three"><div><h3>1 · Payday</h3><p class="sub">Keep bills in Barclays. Fund Monzo Joint and the specific Pots using the transfer schedule.</p></div><div><h3>2 · Each week</h3><p class="sub">Release the weekly allowance, log spending and move true underspends to savings only if upcoming needs are covered.</p></div><div><h3>3 · Every Sunday</h3><p class="sub">Review balances together at 7 pm. Update debts, subscriptions and emergency savings.</p></div></div></div>`}
function budget(f){let m=getMonth(),actuals=id=>sum(state.expenses.filter(x=>isMonth(x.date,month)&&x.category===id).map(x=>x.amount));return `<div class="grid">${metric('Expected income',money(f.income))}${metric('Planned costs',money(f.expenses))}${metric('Savings target',money(m.saveTarget))}${metric('Unallocated',money(f.after),'After optional saving',f.after>=0?'green':'red')}</div><div class="section card"><h2>Income plan</h2><p class="sub">${monthName(month)} · Wages at the previous month-end fund this month. Edit planned receipts if they change.</p><div class="tablewrap"><table><thead><tr><th>Income</th><th class="num">Planned (£)</th><th class="num">Recorded receipts</th></tr></thead><tbody>${state.incomes.map(i=>`<tr><td>${esc(i.name)}</td><td>${num(m.income[i.id],'income|'+i.id)}</td><td class="num">${money(sum(state.receipts.filter(x=>(x.budgetMonth||x.date.slice(0,7))===month&&x.category===i.id).map(x=>x.amount)))}</td></tr>`).join('')}<tr class="foot"><td>Core income</td><td class="num">${money(f.income)}</td><td class="num">${money(f.actualIncome-f.extra)}</td></tr></tbody></table></div>${note('Term-time payments, bonuses and overtime go in Extra income only as received. Universal Credit is £0 until confirmed. PIP is the claimant’s benefit and his needs must take priority.')}</div><div class="card"><div class="section-title"><h2>Expenditure plan</h2><button class="button" data-page="activity">Log spending</button></div><p class="sub">Edit each monthly allowance. Actuals are calculated from the spending log, not internal account transfers.</p><div class="tablewrap"><table><thead><tr><th>Item</th><th>Account</th><th class="num">Plan (£)</th><th class="num">Actual</th><th class="num">Remaining</th></tr></thead><tbody>${state.items.map(i=>`<tr><td>${esc(i.name)}${i.note?`<div class="mini">${esc(i.note)}</div>`:''}</td><td><span class="tag">${esc(accountNames[i.account])}</span></td><td>${num(m.amounts[i.id],'amount|'+i.id)}</td><td class="num">${money(actuals(i.id))}</td><td class="num ${amount(i.id)-actuals(i.id)<0?'red':''}">${money(amount(i.id)-actuals(i.id))}</td></tr>`).join('')}<tr class="foot"><td>Total</td><td></td><td class="num">${money(f.expenses)}</td><td class="num">${money(f.actualSpend)}</td><td class="num">${money(f.expenses-f.actualSpend)}</td></tr></tbody></table></div><div class="formgrid" style="margin-top:16px">${field('Optional emergency savings target (£)',num(m.saveTarget,'month|saveTarget'))}${field('Expected PIP receipt date',valInput(m.pipDate,'month|pipDate','type="date"'))}${field('Expected Child Benefit date',valInput(m.cbDate,'month|cbDate','type="date"'))}</div>${note('Dates after December are estimates based on four-weekly payments. A month can contain two receipts; edit planned income and dates accordingly. Check current statements and missing costs before allocating money.',true)}</div>`}
const potGuide={dance:['♫','Fees, private lessons, competitions, costumes, dancewear, workshops and tickets. Travel comes from transport.'],irregular:['◷','Essential clothing, MOT, repairs, dental/optical costs, annual renewals, birthdays and gifts.'],household:['⌂','Cleaning products, laundry, toilet roll, bin bags, light bulbs and other household consumables. Separate from food.'],personalpet:['♡','Toiletries, haircuts, pet food, litter and routine pet care. Insurance is separate.'],school:['✎','School meals, trips, stationery, home education resources and pocket money.']};
function payday(f){let m=getMonth(),w=weeks(),moves=plannedMoves(),total=0,progress=0;return `<div class="card"><h2>Payday allocation · ${monthName(month)}</h2><p class="sub">Prior month-end wages of ${money(f.wages)}. Check the actual receipts, outstanding bills and arrears first.</p><div class="grid three">${metric('Keep in Barclays Joint',money(f.bills),'Bills, debts, activities and subscriptions')}${metric('Transfer to Monzo Joint',money(f.joint),'Weekly reserve and shared Pots')}${metric('Transfer to personal Monzo',money(f.personal),'Existing personal commitments')}</div>${f.gap?note('Wages do not cover all reserved commitments. Shortfall '+money(f.gap)+'. Rework allocations before transferring.',true):''}<div class="note">These are internal transfers, not additional spending. No new overdraft. If bills are collected from another account, move the existing allowance, not additional money.</div></div><div class="split"><div class="card"><h2>Joint Pots to fund</h2><div class="pot flow-step"><div class="symbol">⇄</div><div class="body"><strong>Weekly Spending Reserve</strong><div class="mini">Groceries, transport and fun. Full month ${money(f.weekly)}; top-up needed ${money(f.topup)}.</div></div><strong>${money(f.initial)}</strong></div>${state.items.filter(i=>i.account==='pot').map(i=>`<div class="pot flow-step"><div class="symbol">${potGuide[i.id]?.[0]||'•'}</div><div class="body"><strong>${esc(i.name)}</strong><div class="mini">${esc(potGuide[i.id]?.[1]||i.group)} Unused funds roll forward.</div></div><strong>${money(amount(i.id))}</strong></div>`).join('')}<div class="pot flow-step"><div class="symbol">◎</div><div class="body"><strong>Emergency Fund</strong><div class="mini">No wage-funded deposit initially. Genuine emergencies only.</div></div><strong>${money(0)}</strong></div></div><div class="card"><h2>Weekly limits</h2><p class="sub">Shared household amounts. Groceries are food/drinks only. House and personal care are separate.</p><div class="tablewrap"><table><thead><tr><th>Week</th><th class="num">Food</th><th class="num">Travel</th><th class="num">Fun</th><th class="num">Total</th></tr></thead><tbody>${w.map(x=>`<tr><td>${dateFmt(x.date)}–${x.end}</td><td class="num">${money(x.food)}</td><td class="num">${money(x.transport)}</td><td class="num">${money(x.fun)}</td><td class="num">${money(x.total)}</td></tr>`).join('')}<tr class="foot"><td>Total</td><td class="num">${money(amount('food'))}</td><td class="num">${money(amount('transport'))}</td><td class="num">${money(amount('fun'))}</td><td class="num">${money(f.weekly)}</td></tr></tbody></table></div><h3 style="margin-top:16px">Weekly spending logged</h3><div class="tablewrap"><table><thead><tr><th>Week starts</th><th class="num">Spent</th><th class="num">Remaining</th></tr></thead><tbody>${w.map(x=>{let spent=sum(state.expenses.filter(e=>e.date>=x.date&&e.date<=month+'-'+String(x.end).padStart(2,'0')&&['food','transport','fun'].includes(e.category)).map(e=>e.amount));return `<tr><td>${dateFmt(x.date)}</td><td class="num">${money(spent)}</td><td class="num ${spent>x.total?'red':''}">${money(x.total-spent)}</td></tr>`}).join('')}</tbody></table></div><p class="small muted">Only includes recorded expenses.</p>${note('At week-end, genuine underspends may be moved to Emergency Fund after checking next week’s needs. Retain money earmarked for a planned outing. Do not spend next week’s reserve early.')}</div></div><div class="card"><div class="section-title"><h2>Transfer checklist</h2><button class="button" data-action="print">Print plan</button></div><p class="sub">Tick when the actual transfer is complete. Amounts may be edited in Actual. The reserve balance uses planned amounts, not bank data.</p><div class="tablewrap"><table><thead><tr><th>Done</th><th>Date</th><th>From → To</th><th class="num">Planned</th><th>Actual (£)</th><th class="num">Reserve after</th></tr></thead><tbody>${moves.map(x=>{if(x.to==='Weekly Spending Reserve')total=round(total+x.amount);if(x.from==='Weekly Spending Reserve')total=round(total-x.amount);let isReserve=x.to==='Weekly Spending Reserve'||x.from==='Weekly Spending Reserve';if(m.moves[x.id]?.done)progress++;return `<tr><td><input type="checkbox" aria-label="Mark ${attr(x.to)} complete" data-edit="moveDone|${x.id}" ${m.moves[x.id]?.done?'checked':''}></td><td class="nowrap">${dateFmt(x.date)}</td><td><strong>${esc(x.to)}</strong><div class="mini">From ${esc(x.from)} · ${esc(x.note)}</div></td><td class="num">${money(x.amount)}</td><td>${num(m.moves[x.id]?.actual,'moveActual|'+x.id)}</td><td class="num ${total<0?'red':''}">${isReserve?money(total):'—'}</td></tr>`}).join('')}</tbody></table></div>${note('Benefit top-ups are conditional on actual receipt and the claimant’s needs. If a projected reserve becomes negative, adjust the dates, spending or available funding. Never allocate unreceived money.',true)}<p class="small muted">${progress} of ${moves.length} marked complete.</p></div><div class="card"><h2>Actual Monzo Joint balances</h2><p class="sub">Enter the balance shown in each Pot when you review your accounts. These are actual amounts, not additional funding or expenditure; carry unused money forward.</p><div class="tablewrap"><table><thead><tr><th>Pot / account</th><th>Actual balance (£)</th><th>Plan for month</th></tr></thead><tbody>${[['reserve','Weekly Spending Reserve',f.weekly],['joint','Monzo Joint main',0],...state.items.filter(i=>i.account==='pot').map(i=>[i.id,i.name,amount(i.id)])].map(([id,n,v])=>`<tr><td>${esc(n)}</td><td>${num(id==='joint'?state.settings.joint:state.settings.potBalances?.[id],'potBalance|'+id)}</td><td class="num">${money(v)}</td></tr>`).join('')}<tr><td>Emergency Fund</td><td>${num(state.settings.emergency,'setting|emergency')}</td><td class="num">${money(m.saveTarget)}</td></tr></tbody></table></div></div><div class="card"><h2>Which account do we use?</h2><div class="tablewrap"><table><tbody><tr><td>Barclays Joint</td><td>Income, bills and debt payments only. No everyday card spending.</td></tr><tr><td>Monzo Joint main</td><td>This week’s food, transport and treats; withdraw earmarked Pot money just before paying a separate expense.</td></tr><tr><td>Monzo Joint Pots</td><td>Reserved future spending. For a mixed supermarket shop, split the receipt by item type; do not count it twice.</td></tr><tr><td>Emergency Fund</td><td>Unexpected essential costs; no holidays, optional electronics or impulse spending.</td></tr></tbody></table></div></div>`}
function debts(f){let known=state.debts.filter(x=>x.balance!==null&&x.balance!==undefined),unknown=state.debts.filter(x=>x.balance==null).length;return `<div class="grid">${metric('Starting identified debt',money(f.start),'Imported baseline')}${metric('Latest identified debt',money(f.debt),`${unknown} unknown balances`)}${metric('Net reduction',money(f.start-f.debt),'May include newly identified debts',f.start-f.debt>=0?'green':'red')}${metric('Recorded required payments',money(sum(state.debts.map(d=>d.payment))),'Not the full budget reserve')}</div><div class="section card"><div class="section-title"><h2>Debt register</h2><div class="row"><button class="button" data-action="snapshot">Save monthly snapshot</button><button class="button" data-action="addDebt">+ Add debt</button></div></div><p class="sub">Update balances from your apps and statements. Leave unknown balances blank. £0 means confirmed cleared, not unknown.</p><div class="tablewrap"><table><thead><tr><th>Creditor</th><th class="num">Starting</th><th>Current (£)</th><th>Rate / status</th><th>Required (£)</th><th>Next / expiry</th><th>Balance date</th></tr></thead><tbody>${state.debts.map(d=>`<tr><td>${esc(d.name)}<div class="mini">${esc(d.note)}</div>${d.balance===0?'<span class="tag good">Cleared</span>':d.balance==null?'<span class="tag warning">Confirm balance</span>':''}</td><td class="num">${d.start==null?'—':money(d.start)}</td><td>${num(d.balance,'debt|'+d.id+'|balance')}</td><td>${valInput(d.rate,'debt|'+d.id+'|rate','class="wide"')}</td><td>${num(d.payment,'debt|'+d.id+'|payment')}</td><td>${valInput(d.due,'debt|'+d.id+'|due','class="wide"')}</td><td>${valInput(d.date,'debt|'+d.id+'|date','class="wide"')}</td></tr>`).join('')}</tbody></table></div>${note('Updating a debt balance does not automatically change your monthly budget. Check the actual required repayment, then update the relevant allowance in Monthly budget. Next/PayPal and Klarna are combined reserves. No overpayments at the expense of essentials.')}</div><div class="split"><div class="card"><h2>Repayment order</h2><div class="timeline"><div><strong>First: essential bills and all required payments</strong><p class="mini">Maintain DWP and existing instalments. Build a cash buffer.</p></div><div><strong>High-cost balances</strong><p class="mini">Barclaycard 35.9% compound, Creation 34.9% (verify current rate), Argos interest-bearing portion, then Monzo Flex 29%. Compare current like-for-like rates before paying extra.</p></div><div><strong>Next and Novuna</strong><p class="mini">Next 24.9%; Novuna 15.9%. Confirm Barclays loan APR and EE terms first.</p></div><div><strong>Protect promotional expiries</strong><p class="mini">${planText('promos','Check promotional end dates and plan repayments before expiry.')}</p></div></div></div><div class="card"><h2>Debt breakdown</h2>${known.filter(x=>x.balance>0).sort((a,b)=>b.balance-a.balance).map(d=>`<div class="row between"><span class="small">${esc(d.name)}</span><strong class="small">${money(d.balance)}</strong></div><div class="bar"><div style="width:${d.balance/Math.max(1,f.debt)*100}%"></div></div>`).join('')}</div></div><div class="card"><h2>Debt history</h2><p class="sub">Snapshots preserve each creditor’s balance for that month; saving again replaces that month’s snapshot.</p>${state.snapshots.length?`<div class="tablewrap"><table><thead><tr><th>Month</th><th class="num">Identified total</th><th>Unknown balances</th><th></th></tr></thead><tbody>${state.snapshots.slice().sort((a,b)=>b.month.localeCompare(a.month)).map(x=>`<tr><td>${esc(monthName(x.month))}</td><td class="num">${money(sum(Object.values(x.balances)))}</td><td>${Object.values(x.balances).filter(v=>v==null).length}</td><td><details><summary>Details</summary>${Object.entries(x.balances).map(([id,v])=>`<div>${esc(state.debts.find(d=>d.id===id)?.name||id)}: ${v==null?'Unknown':money(v)}</div>`).join('')}</details></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No monthly snapshots yet. Save the current balances at month-end.</div>'}</div>`}
function subscriptions(f){let ss=state.subscriptions,c=ss.filter(x=>x.status==='Cancelled'),verified=sum(c.filter(x=>x.current!=null).map(x=>x.current)),active=sum(ss.filter(x=>x.status==='Keep'&&x.current!=null).map(x=>x.current));return `<div class="grid">${metric('Monthly subscription cap',money(amount('subscriptions')),'Existing budget target')}${metric('Cancelled',`${c.length} / ${ss.length}`,'Review historical charges first')}${metric('Verified monthly fees cancelled',money(verified),'Only entered recurring fees')}${metric('Verified kept fees',money(active),'Unknown fees excluded')}</div><div class="section card"><div class="section-title"><h2>Subscription checklist</h2><button class="button" data-action="addSub">+ Add service</button></div><p class="sub">${planText('subs','Historical spending is not a confirmed subscription list. Enter actual recurring fees and tick Cancelled when confirmed.')}</p><div class="tablewrap"><table><thead><tr><th>Cancelled</th><th>Service / charge</th><th class="num">Observed</th><th>Current monthly fee (£)</th><th>Decision</th><th>Cancelled date</th></tr></thead><tbody>${ss.map(s=>`<tr><td><input type="checkbox" aria-label="${attr(s.name)} cancelled" data-edit="subCancel|${s.id}" ${s.status==='Cancelled'?'checked':''}></td><td>${s.status==='Cancelled'?'<span style="text-decoration:line-through">'+esc(s.name)+'</span>':esc(s.name)}<div class="mini">${esc(s.note)}</div></td><td class="num">${money(s.observed)}<div class="mini">${esc(s.period)}</div></td><td>${num(s.current,'sub|'+s.id+'|current')}</td><td><select data-edit="sub|${s.id}|status">${opts([['Review','Review'],['Keep','Keep'],['Cancelled','Cancelled'],['One-off','One-off / not recurring']],s.status)}</select></td><td>${valInput(s.cancelDate,'sub|'+s.id+'|cancelDate','type="date"')}</td></tr>`).join('')}</tbody></table></div>${note('Cancelling a subscription here is only a record. Cancel with the service provider and verify that payments have stopped. The budget cap already assumes reductions; do not add estimated savings to the budget again. Keep necessary family, education and work services.')}</div>`}
function entryTable(rows,kind,columns){return rows.length?`<div class="tablewrap"><table><thead><tr>${columns.map(x=>`<th>${esc(x[0])}</th>`).join('')}<th></th></tr></thead><tbody>${rows.slice().reverse().map(r=>`<tr>${columns.map(x=>`<td>${x[1](r)}</td>`).join('')}<td><button class="button danger" data-action="delete|${kind}|${r.id}">Remove</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No entries recorded.</div>'}
function activity(f){let exp=state.expenses.filter(x=>isMonth(x.date,month)),rec=state.receipts.filter(x=>(x.budgetMonth||x.date.slice(0,7))===month),extra=state.extra.filter(x=>isMonth(x.date,month)),savings=state.savings.filter(x=>isMonth(x.date,month));let date=month===today().slice(0,7)?today():month+'-01';const dateInput=`<input type="date" name="date" required value="${date}">`;return `<div class="grid">${metric('Core receipts logged',money(sum(rec.map(x=>x.amount))))}${metric('Extra net received',money(f.extra))}${metric('Spending logged',money(f.actualSpend))}${metric('Emergency fund',money(state.settings.emergency),'Actual tracked balance')}</div><div class="section split"><div class="card"><h2>Record an expense</h2><form data-form="expense" class="formgrid">${field('Date',dateInput)}${field('Category',`<select name="category" required>${opts(state.items.map(i=>[i.id,i.name]),'food')}</select>`)}${field('Amount (£)','<input name="amount" type="number" min="0.01" step="0.01" required>')}${field('Description','<input name="note" placeholder="e.g. Lidl food shop">')}<button class="button primary">Add expense</button></form><p class="small muted">Record actual household cash expenditure once. Do not log internal transfers, reserve deposits or the same card purchase and repayment as cash expenditure. New credit purchases should be reflected in debt balances.</p></div><div class="card"><h2>Record a core receipt</h2><form data-form="receipt" class="formgrid">${field('Budget month',`<input type="month" name="budgetMonth" value="${month}" required>`)}${field('Receipt date',dateInput)}${field('Income source',`<select name="category">${opts(state.incomes.map(i=>[i.id,i.name]),'salary')}</select>`)}${field('Amount (£)','<input name="amount" type="number" min="0.01" step="0.01" required>')}<button class="button primary">Add receipt</button></form><p class="small muted">Record month-end wages against the month they fund. Extra receipts go below.</p></div></div><div class="card"><h2>Unexpected & term-time income</h2>${note('Keep extra receipts in Barclays first. Cover shortfalls and tax/benefit reserves, build the Emergency Fund to your target, then repay high-interest debt. Refunds/reimbursements return to their original Pot and are not new income.')}
<form data-form="extra" class="formgrid">${field('Date',dateInput)}${field('Source','<input name="source" placeholder="Term-time work, bonus, gift…" required>')}${field('Received (£)','<input name="amount" type="number" min="0.01" step="0.01" required>')}${field('Tax / benefit reserve (£)','<input name="tax" type="number" min="0" step="0.01" value="0">')}${field('Essential shortfalls (£)','<input name="essential" type="number" min="0" step="0.01" value="0">')}${field('To Emergency Fund (£)','<input name="emergency" type="number" min="0" step="0.01" value="0">')}${field('To debt (£)','<input name="debt" type="number" min="0" step="0.01" value="0">')}${field('Notes','<input name="note" placeholder="Which debt / Pot">')}<button class="button primary">Record extra income</button></form><p class="small muted">Enter actual allocations, not promises. Emergency deposits recorded here update the tracked balance; debt balances must be updated separately.</p>${entryTable(extra,'extra',[['Date',r=>dateFmt(r.date)],['Source',r=>esc(r.source)],['Received',r=>money(r.amount)],['Tax reserve',r=>money(r.tax)],['Essential',r=>money(r.essential)],['Saved',r=>money(r.emergency)],['Debt',r=>money(r.debt)],['Unallocated',r=>money(r.amount-r.tax-r.essential-r.emergency-r.debt)]])}</div><div class="card"><h2>Emergency Fund movements</h2><form data-form="saving" class="formgrid">${field('Date',dateInput)}${field('Movement','<select name="direction"><option value="in">Deposit</option><option value="out">Withdrawal</option></select>')}${field('Amount (£)','<input name="amount" type="number" min="0.01" step="0.01" required>')}${field('Reason','<input name="note" placeholder="Weekly underspend, emergency…" required>')}<button class="button primary">Record movement</button></form><p class="small muted">Use for planned savings, weekly underspends and emergency withdrawals. Do not record again if already entered in Extra income. Reconcile the tracked balance during Sunday review.</p>${entryTable(savings,'savings',[['Date',r=>dateFmt(r.date)],['Reason',r=>esc(r.note)],['Movement',r=>`${r.direction==='out'?'−':'+'}${money(r.amount)}`]])}</div><div class="card"><h2>Spending history · ${monthName(month)}</h2>${entryTable(exp,'expenses',[['Date',r=>dateFmt(r.date)],['Category',r=>esc(state.items.find(i=>i.id===r.category)?.name||r.category)],['Description',r=>esc(r.note)],['Amount',r=>money(r.amount)]])}</div><div class="card"><h2>Core receipt history</h2>${entryTable(rec,'receipts',[['Receipt date',r=>dateFmt(r.date)],['Source',r=>esc(state.incomes.find(i=>i.id===r.category)?.name||r.category)],['Amount',r=>money(r.amount)]])}</div>`}
function review(f){let date=today(),r=state.reviews.slice().sort((a,b)=>b.date.localeCompare(a.date)),weekChecks=['Check Barclays and Monzo Joint balances','Check credit card and loan balances','Review all spending against weekly allowance','Check bills and minimums due in next seven days','Record Term-time payments and other income','Check no new non-essential borrowing','Reconcile emergency savings','Agree one action for next week'];return `<div class="card"><h2>Sunday check-in · 7 pm</h2><p class="sub">15 minutes together. Focus on what is affordable this week, not on blame or clearing everything immediately.</p><form data-form="review"><div class="formgrid">${field('Review date',`<input type="date" name="date" value="${date}" required>`)}${field('Barclays available (£)',`<input type="number" step="0.01" name="barclays" value="${state.settings.barclays??''}">`)}${field('Monzo Joint main (£)',`<input type="number" step="0.01" name="joint" value="${state.settings.joint??''}">`)}${field('Emergency Fund actual (£)',`<input type="number" min="0" step="0.01" name="emergency" value="${state.settings.emergency}">`)}${field('Weekly reserve actual (£)','<input type="number" min="0" step="0.01" name="reserve">')}${field('Food spent this week (£)','<input type="number" min="0" step="0.01" name="food">')}${field('Transport spent (£)','<input type="number" min="0" step="0.01" name="transport">')}${field('Fun spent (£)','<input type="number" min="0" step="0.01" name="fun">')}</div><div class="section">${weekChecks.map((t,i)=>`<label class="checkline"><input type="checkbox" name="check" value="${i}"><span>${esc(t)}</span></label>`).join('')}</div><div class="field" style="margin:14px 0"><label>Notes / action for next week</label><textarea name="note" placeholder="Upcoming bills, spending pressures, one action…"></textarea></div><button class="button primary">Save weekly review</button></form></div><div class="card"><h2>Past reviews</h2>${entryTable(r.reverse(),'reviews',[['Date',x=>dateFmt(x.date)],['Barclays',x=>x.barclays==null?'—':money(x.barclays)],['Joint balance',x=>x.joint==null?'—':money(x.joint)],['Emergency',x=>x.emergency==null?'—':money(x.emergency)],['Checklist',x=>`${x.checks.length}/8`],['Action',x=>esc(x.note)]])}</div>`}
function goals(f){let m=getMonth(),gap=round(f.expenses-(f.income-inc('pip'))),one=Number(state.settings.oneChild)||0,oneGap=round(f.expenses-(f.wages+one+inc('uc'))),wageGap=round(f.expenses-f.wages),release=sum(state.debts.filter(d=>d.balance===0).map(d=>d.payment));return `<div class="grid">${metric('No PIP: monthly gap',money(Math.max(0,gap)),'Before optional savings')}${metric('No PIP + one-child CB gap',money(Math.max(0,oneGap)),'Illustrative current-rate scenario')}${metric('Wages-only gap',money(Math.max(0,wageGap)),'Before optional savings')}${metric('Extra earnings target',money(state.settings.extraTarget),'Net each month')}</div><div class="section split"><div class="card"><h2>Reduce reliance on the claimant’s benefits</h2><p>${planText('benefits','Protect disability-related needs and check entitlement changes with a benefits adviser.')}</p><div class="formgrid">${field('PIP reserved for claimant (£/month)',num(state.settings.pipReserved,'setting|pipReserved'))}${field('One-child CB scenario (£)',num(state.settings.oneChild,'setting|oneChild'))}${field('Additional net income target (£)',num(state.settings.extraTarget,'setting|extraTarget'))}</div><div class="note">If ${money(state.settings.pipReserved)} of PIP is reserved, the projected ordinary household surplus is <strong>${money(f.surplus-state.settings.pipReserved)}</strong> before optional savings. Recheck the payday top-up and any overlap with disability costs.</div><p class="small muted">This is a planning scenario, not a benefits entitlement assessment. Use actual payment amounts, not future rate assumptions.</p></div><div class="card"><h2>Milestones</h2><div class="timeline">${(state.privatePlan?.milestones||[['Stabilise','Protect essentials and avoid new borrowing.'],['Build breathing room','Build a cash buffer and reduce high-cost debt.'],['Review benefits','Check eligibility with an adviser.']]).map(([title,description])=>`<div><strong>${esc(title)}</strong><p class="mini">${esc(description)}</p></div>`).join('')}</div></div></div><div class="card"><h2>Household operating rules</h2><div class="timeline"><div><strong>1. Protect essentials</strong><p class="mini">Housing, council tax, food, energy, essential travel, disability-related costs and required repayments first. If unaffordable, contact creditors and free debt advice.</p></div><div><strong>2. Use the right account</strong><p class="mini">Barclays receives income and pays bills. Monzo Joint main holds this week’s spending only; Pots are earmarked. Never count transfers as spending.</p></div><div><strong>3. Control food and subscriptions</strong><p class="mini">${planText('food','Plan food shopping and review subscription costs.')}</p></div><div><strong>4. Extra income</strong><p class="mini">${planText('extra','Fund shortfalls and tax first, then build the emergency fund and reduce expensive debt.')}</p></div><div><strong>5. Review regularly</strong><p class="mini">Sunday 7 pm, 15 minutes together. Update monthly debt snapshots. Redirect payments only once debts have actually ended.</p></div></div>${note('Free support: <a href="https://www.stepchange.org/" target="_blank" rel="noopener">StepChange</a> · 0800 138 1111. Seek help if essential bills or minimums are unaffordable.')}</div>`}
function settings(f){return `<div class="card"><h2>Shared data and privacy</h2>${note('Both authorised accounts access one shared cloud record. Financial data is not bundled into the website or stored in browser local storage. Keep private backups; sign out when finished on a shared device. Both authorised users can see all household data.')}<div class="row"><button class="button primary" data-action="export">Export JSON backup</button><button class="button" data-action="import">Import / replace backup</button><button class="button" data-action="retry">Retry saving</button><button class="button" data-action="reload">Reload shared record</button><button class="button" data-action="reauth">Re-authenticate</button><button class="button" data-action="print">Print current page</button></div><p class="small muted">Backups contain private financial information. Never upload them to GitHub. Import replaces the entire shared record. The site does not connect to banks, initiate transfers or cancel subscriptions.</p></div><div class="card"><h2>Editable recovery targets</h2><div class="formgrid">${field('Emergency fund target (£)',num(state.settings.target,'setting|target','min="1"'))}${field('Actual emergency balance (£)',num(state.settings.emergency,'setting|emergency'))}${field('Indicative term-time income (£)',num(state.settings.danceEstimate,'setting|danceEstimate'))}${field('Net extra income target (£)',num(state.settings.extraTarget,'setting|extraTarget'))}${field('PIP reference payment date',valInput(state.settings.pipAnchor,'setting|pipAnchor','type="date"'))}${field('Child Benefit reference payment date',valInput(state.settings.cbAnchor,'setting|cbAnchor','type="date"'))}</div><p class="small muted">Reference dates estimate future four-weekly payments. Confirm actual dates and change the budget month’s expected receipts when needed.</p></div><div class="card"><h2>Source & assumptions</h2><p class="sub">${planText('source','Imported household plan. Verify actual balances, repayment amounts, benefit dates and missing expenses.')}</p></div>`}
function updateEdit(el){let [kind,id,key]=el.dataset.edit.split('|'),v=el.type==='number'?number(el.value):el.value,m=getMonth();if(el.type==='number'&&v!=null&&(!Number.isFinite(v)||v<0)){notify('Enter a valid non-negative amount.');render();return}switch(kind){case 'income':m.income[id]=v??0;break;case 'amount':m.amounts[id]=v??0;break;case 'month':m[id]=v??0;break;case 'potBalance':if(id==='joint'){state.settings.joint=v??0}else{state.settings.potBalances=state.settings.potBalances||{};state.settings.potBalances[id]=v}break;case 'setting':state.settings[id]=id==='target'?Math.max(1,v||1):v??0;break;case 'debt':{let d=state.debts.find(x=>x.id===id);if(d){d[key]=v;if(key==='balance'&&v!==null)d.date=today();}break}case 'sub':{let s=state.subscriptions.find(x=>x.id===id);s[key]=v;if(key==='status'){if(v==='Cancelled'&&!s.cancelDate)s.cancelDate=today();if(v!=='Cancelled')s.cancelDate=''}break}case 'subCancel':{let s=state.subscriptions.find(x=>x.id===id);s.status=el.checked?'Cancelled':'Review';s.cancelDate=el.checked?today():'';break}case 'moveDone':{let x=plannedMoves().find(x=>x.id===id);m.moves[id]={...m.moves[id],done:el.checked};if(el.checked&&m.moves[id].actual==null)m.moves[id].actual=x.amount;break}case 'moveActual':m.moves[id]={...m.moves[id],actual:v};break;}save();render()}
function backup(){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.href=url;a.download=`household-finance-backup-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);notify('Backup exported. Keep it private.');}
function validData(d){
 const obj=x=>x!==null&&typeof x==='object'&&!Array.isArray(x), validMonth=/^\d{4}-(0[1-9]|1[0-2])$/;
 return !!(obj(d)&&d.schema===1&&obj(d.settings)&&Array.isArray(d.items)&&Array.isArray(d.incomes)&&Array.isArray(d.debts)&&Array.isArray(d.subscriptions)&&obj(d.months)&&Object.keys(d.months).length>0&&Object.entries(d.months).every(([k,v])=>validMonth.test(k)&&obj(v)&&obj(v.amounts)&&obj(v.income)&&obj(v.moves))&&['expenses','receipts','extra','snapshots','reviews','savings'].every(k=>Array.isArray(d[k]))&&d.items.every(x=>obj(x)&&typeof x.id==='string'&&typeof x.name==='string')&&d.debts.every(obj)&&d.subscriptions.every(obj)&&d.incomes.every(obj)&&(!d.privatePlan?.milestones||Array.isArray(d.privatePlan.milestones)&&d.privatePlan.milestones.every(x=>Array.isArray(x)&&x.length===2)));
}
function adoptData(d,keepMonth=false){if(!validData(d))throw Error('invalid data');state=d;const keys=Object.keys(state.months).sort();if(!keepMonth||!state.months[month])month=keys[keys.length-1];}
function perform(action){const [type,kind,id]=action.split('|');switch(type){case 'export':backup();return;case 'import':$('#importFile').click();return;case 'print':window.print();return;case 'retry':if(conflict){notify('Export a backup, reload the shared record, then reconcile changes.');return}save();return;case 'reload':reloadCloud();return;case 'reauth':showReauth();return;case 'snapshot':{const balances=Object.fromEntries(state.debts.map(d=>[d.id,d.balance??null]));if(state.snapshots.some(x=>x.month===month)&&!confirm('Replace the existing snapshot for '+monthName(month)+'?'))return;state.snapshots=state.snapshots.filter(x=>x.month!==month);state.snapshots.push({month,balances,date:today()});notify('Monthly debt snapshot saved.');break}case 'addDebt':{let name=prompt('Creditor / plan name');if(!name||!name.trim())return;state.debts.push({id:uid(),name:name.trim(),date:'',balance:null,start:null,rate:'Unknown',payment:null,due:'',note:'Newly identified balance. Update the monthly budget separately.'});break}case 'addSub':{let name=prompt('Service name');if(!name||!name.trim())return;state.subscriptions.push({id:uid(),name:name.trim(),observed:0,period:'Added manually',current:null,status:'Review',cancelDate:'',note:'Confirm recurring fee.'});break}case 'delete':{if(!['expenses','receipts','extra','reviews','savings'].includes(kind))return;if(!confirm('Remove this recorded entry?'))return;let x=state[kind].find(r=>r.id===id);if(!x)return;if(kind==='extra')state.settings.emergency=round(state.settings.emergency-x.emergency);if(kind==='savings')state.settings.emergency=round(state.settings.emergency-(x.direction==='out'?-x.amount:x.amount));state[kind]=state[kind].filter(r=>r.id!==id);if(state.settings.emergency<0){state.settings.emergency=0;notify('Reconcile your emergency balance in Sunday review.')}break}default:return}save();render()}
function submitForm(form){let fd=new FormData(form),obj=Object.fromEntries(fd),type=form.dataset.form,record={id:uid(),date:obj.date};const get=k=>round(Number(obj[k]||0));if(!obj.date)return;switch(type){case 'expense':state.expenses.push({...record,category:obj.category,amount:get('amount'),note:obj.note});break;case 'receipt':state.receipts.push({...record,budgetMonth:obj.budgetMonth,category:obj.category,amount:get('amount')});break;case 'extra':{let e={...record,source:obj.source,amount:get('amount'),tax:get('tax'),essential:get('essential'),emergency:get('emergency'),debt:get('debt'),note:obj.note};if(sum([e.tax,e.essential,e.emergency,e.debt])>e.amount){notify('Allocations cannot exceed the amount received.');return}state.extra.push(e);state.settings.emergency=round(state.settings.emergency+e.emergency);break}case 'saving':{let a=get('amount'),delta=obj.direction==='out'?-a:a;if(round(state.settings.emergency+delta)<0){notify('Withdrawal exceeds the tracked emergency balance. Reconcile it first.');return}state.savings.push({...record,amount:a,direction:obj.direction,note:obj.note});state.settings.emergency=round(state.settings.emergency+delta);break}case 'review':{let r={...record,barclays:number(obj.barclays),joint:number(obj.joint),emergency:number(obj.emergency),reserve:number(obj.reserve),food:number(obj.food),transport:number(obj.transport),fun:number(obj.fun),checks:fd.getAll('check'),note:obj.note};state.reviews.push(r);for(let k of ['barclays','joint','emergency'])if(r[k]!==null)state.settings[k]=r[k];break}default:return}save();render();notify('Entry recorded. Check the cloud save indicator.');}
document.addEventListener('click',e=>{let t=e.target.closest('[data-page],[data-action]');if(!t||!state||!shared||!t.closest('#app'))return;if(t.dataset.page){page=t.dataset.page;render();window.scrollTo({top:0,behavior:'instant'});}else if(t.dataset.action)perform(t.dataset.action);});
document.addEventListener('change',e=>{if(shared&&state&&e.target.dataset.edit)updateEdit(e.target)});
document.addEventListener('submit',e=>{if(shared&&state&&e.target.dataset.form){e.preventDefault();submitForm(e.target)}});
$('#month').addEventListener('change',e=>{if(shared&&state&&e.target.value){month=e.target.value;getMonth();render()}});
$('#exportBtn').addEventListener('click',()=>{if(state)backup()});
$('#importFile').addEventListener('change',async e=>{const file=e.target.files[0];if(!file||!shared)return;try{const data=JSON.parse(await file.text());if(!validData(data))throw Error('Invalid backup');if(state&&!confirm('Replace the entire shared household record with this backup? Both users will see the replacement.'))return;if(conflict||pendingWrites){notify('Finish saving or resolve the conflict before importing.');return;}adoptData(data);page='overview';showApp();save();render();notify('Backup imported. Check the cloud save indicator.');}catch(err){showGateMessage('Cannot import this file: choose a valid household JSON backup.');notify('Cannot import this file: choose a valid household JSON backup.');}finally{e.target.value='';}});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});

function showGateMessage(message){$('#gateMessage').textContent=message;}
function showApp(){ $('#gate').hidden=true;$('#app').hidden=false;$('#loginForm').hidden=true;$('#firstImport').hidden=true;$('#signOut').hidden=false; }
function showGate(message=''){ $('#app').hidden=true;$('#gate').hidden=false;$('#loginForm').hidden=false;$('#firstImport').hidden=true;$('#signOut').hidden=true;showGateMessage(message); }
function clearApp(){ $('#content').replaceChildren();$('#nav').replaceChildren();$('#month').value='';$('#title').textContent='Overview';state=null;shared=false;revision=0;dirty=false;conflict=false;pendingWrites=0;editVersion=0;ownerId=null;sessionGeneration++;queue=Promise.resolve(); }
async function connectRecord(){
 const row=await Cloud.read();
 if(!row)throw Error('not authorised');
 revision=row.revision;shared=true;ownerId=Cloud.userId();conflict=false;dirty=false;
 if(row.data===null){$('#app').hidden=true;$('#gate').hidden=false;$('#loginForm').hidden=true;$('#firstImport').hidden=false;$('#signOut').hidden=false;showGateMessage('Signed in. This household has no data yet. Import your private household JSON file once; the other account will see the same record.');return;}
 adoptData(row.data);showApp();setStatus('Cloud · saved');render();
}
let polling=false;
async function syncRecord(){
 if(!shared||!$('#gate').hidden&&state!==null||dirty||conflict||pendingWrites||polling||document.activeElement?.matches('input,textarea,select'))return;
 const generation=sessionGeneration;polling=true;
 try{const row=await Cloud.read();if(generation!==sessionGeneration||dirty||pendingWrites||conflict)return;if(!row){await logout(true);showGateMessage('This account no longer has access.');return;}if(row.revision>revision&&validData(row.data)){revision=row.revision;adoptData(row.data,true);showApp();render();setStatus('Cloud · synced');}}
 catch(e){if(generation===sessionGeneration)setStatus(e.message==='session'?'Session expired · sign in again':'Cloud unavailable · retry');}
 finally{polling=false;}
}
async function reloadCloud(){if(!shared)return;if(dirty&&!confirm('Discard unsaved local edits? Export a JSON backup first if you need them.'))return;await queue;try{const row=await Cloud.read();if(!row||!validData(row.data))throw Error();adoptData(row.data,true);revision=row.revision;dirty=false;conflict=false;pendingWrites=0;setStatus('Cloud · synced');render();}catch(e){notify('Could not reload. Check connection and login.');}}
async function logout(force=false){if(!force&&dirty&&!confirm('Unsaved changes may be lost. Export a backup first. Sign out anyway?'))return;await queue;clearApp();await Cloud.logout();showGate('Signed out. Sign in again to access your household.');}
async function showReauth(){if(!state)return;await queue;$('#gate').hidden=false;$('#app').hidden=true;$('#loginForm').hidden=false;$('#firstImport').hidden=true;$('#signOut').hidden=false;showGateMessage('Sign in again to restore the session. Unsaved edits remain in memory.');}
$('#loginForm').addEventListener('submit',async e=>{e.preventDefault();const button=$('#loginButton'),f=new FormData(e.target);button.disabled=true;showGateMessage('Signing in…');try{const wasShared=shared&&state!==null;const oldUser=ownerId;await Cloud.signIn(String(f.get('email')).trim(),String(f.get('password')));if(wasShared&&dirty){if(oldUser!==Cloud.userId()){await Cloud.logout();throw Error('different user');}const row=await Cloud.read();if(!row)throw Error('not authorised');if(row.revision!==revision){conflict=true;setStatus('Conflict · export before reloading');}else setStatus('Unsaved edits · retry saving');showApp();render();}else await connectRecord();}catch(err){if(!state){await Cloud.logout();clearApp();showGate();}showGateMessage(err.message==='not authorised'?'This login is not authorised for the household. Ask the project owner to add its user ID.':err.message==='different user'?'Use the original account to recover unsaved edits.':'Unable to sign in or load the shared record. Check login, project configuration and database setup.');}finally{button.disabled=false;e.target.elements.password.value='';}});
$('#signOut').addEventListener('click',()=>logout());$('#appSignOut').addEventListener('click',()=>logout());$('#initialImport').addEventListener('click',()=>$('#importFile').click());
if(!Cloud.configured()){showGate('Setup required: configure the project URL and publishable key in config.js, then run the supplied database setup.');$('#loginButton').disabled=true;}else showGate('Sign in with an authorised household account.');
setInterval(syncRecord,12000);
